@namespace sv_62cf6b2af18a4a4daf0b25f7a6865164.Components.Pages.Apply

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var cssClass = GetStepClass(stepIndex);
        <div class="step @cssClass" @onclick="() => HandleStepClick(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < CurrentStep)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (stepIndex < StepNames.Count - 1)
        {
            <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "dimmed";
    }

    private async Task HandleStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

@namespace sv_62cf6b2af18a4a4daf0b25f7a6865164.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name</label>
        <input type="text" class="form-control" value="@Entry.Company"
               @onchange="e => UpdateEntry(Entry with { Company = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Job Title</label>
        <input type="text" class="form-control" value="@Entry.Title"
               @onchange="e => UpdateEntry(Entry with { Title = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date</label>
            <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateEntry(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="e => UpdateEntry(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Entry.Description"
                  @onchange="e => UpdateEntry(Entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null;

    private async Task UpdateEntry(WorkEntry updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }

    private async Task ToggleCurrent(bool isCurrent)
    {
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        await OnEntryChanged.InvokeAsync(updated);
    }
}

@namespace sv_62cf6b2af18a4a4daf0b25f7a6865164.Components.Pages.Apply

<div class="reference-form">
    <h4>Reference @(Index + 1)</h4>

    <div class="form-group">
        <label>Name</label>
        <input type="text" class="form-control" value="@Reference.Name"
               @onchange="e => Update(Reference with { Name = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Relationship</label>
        <input type="text" class="form-control" value="@Reference.Relationship"
               @onchange="e => Update(Reference with { Relationship = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email</label>
            <input type="email" class="form-control" value="@Reference.Email"
                   @onchange="e => Update(Reference with { Email = (string?)e.Value ?? string.Empty })" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" class="form-control" value="@Reference.Phone"
                   @onchange="e => Update(Reference with { Phone = (string?)e.Value ?? string.Empty })" />
        </div>
    </div>

    @if (ShowRemove)
    {
        <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public Reference Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<Reference> OnReferenceChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task Update(Reference updated)
    {
        await OnReferenceChanged.InvokeAsync(updated);
    }
}

