</div>

@code {
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;
    private string coverLetter = string.Empty;

    protected override void OnParametersSet()
    {
        if (CoverLetter is not null)
        {
            coverLetter = CoverLetter;
        }
    }

    private void OnInput(ChangeEventArgs e)
    {
        coverLetter = (string?)e.Value ?? string.Empty;
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(coverLetter);
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}
