@namespace sv_62cf6b2af18a4a4daf0b25f7a6865164.Components.Pages.Apply

<div class="step-content">
    <h3>References</h3>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="alert alert-danger">@errorMessage</div>
    }

    @for (int i = 0; i < references.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="references[index]"
                       Index="index"
                       ShowRemove="references.Count > 2"
                       OnReferenceChanged="r => UpdateReference(index, r)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (references.Count < 3)
    {
        <button type="button" class="btn btn-outline-secondary" @onclick="AddReference">
            + Add Reference
        </button>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-secondary" @onclick="HandleBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<Reference> references = new();
    private string? errorMessage;

    protected override void OnParametersSet()
    {
        if (References is not null && References.Count > 0)
        {
            references = References.ToList();
        }
        else if (references.Count == 0)
        {
            references.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
            references.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
        }
    }

    private void UpdateReference(int index, Reference reference)
    {
        references[index] = reference;
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
        {
            references.RemoveAt(index);
        }
    }

    private void AddReference()
    {
        if (references.Count < 3)
        {
            references.Add(new Reference(string.Empty, string.Empty, string.Empty, string.Empty));
        }
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
            {
                errorMessage = "Each reference requires at least a name and email.";
                return;
            }
        }

        await OnNext.InvokeAsync(references.ToList());
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

