@namespace sv_62cf6b2af18a4a4daf0b25f7a6865164.Components.Pages.Apply

<div class="step-content">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea class="form-control cover-letter-textarea" rows="12"
                  maxlength="@MaxLength"
                  @oninput="OnInput"
                  value="@coverLetter"></textarea>
        <div class="char-count @(coverLetter.Length > MaxLength ? "over-limit" : "")">
            @coverLetter.Length / @MaxLength characters
        </div>
    </div>

    <div class="step-buttons">
        <button type="button" class="btn btn-secondary" @onclick="HandleBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;
    private string coverLetter = string.Empty;

    protected override void OnParametersSet()
    {
        if (CoverLetter is not null)
        {
            coverLetter = CoverLetter;
        }
    }

    private void OnInput(ChangeEventArgs e)
    {
        coverLetter = (string?)e.Value ?? string.Empty;
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(coverLetter);
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

