@namespace sv_62cf6b2af18a4a4daf0b25f7a6865164.Components.Pages.Apply
@using sv_62cf6b2af18a4a4daf0b25f7a6865164.Services

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (isSubmitted)
    {
        <div class="alert alert-success">
            <h4>Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@applicationId</strong></p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(errorMessage))
        {
            <div class="alert alert-danger">@errorMessage</div>
        }

        <div class="review-section">
            <div class="review-header">
                <h4>Personal Information</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            @if (Personal is not null)
            {
                <dl>
                    <dt>Name</dt><dd>@Personal.FullName</dd>
                    <dt>Email</dt><dd>@Personal.Email</dd>
                    <dt>Phone</dt><dd>@Personal.Phone</dd>
                    <dt>Address</dt><dd>@Personal.Address</dd>
                </dl>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>Work History</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @if (Work is not null)
            {
                @foreach (var entry in Work.Entries)
                {
                    <div class="review-entry">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <span class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") &ndash;
                            @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                        </span>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p>@entry.Description</p>
                        }
                    </div>
                }
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>References</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @if (References is not null)
            {
                @foreach (var reference in References)
                {
                    <div class="review-entry">
                        <strong>@reference.Name</strong> (@reference.Relationship)<br />
                        <span class="text-muted">@reference.Email | @reference.Phone</span>
                    </div>
                }
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>Cover Letter</h4>
                <button type="button" class="btn btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        <div class="step-buttons">
            <button type="button" class="btn btn-secondary" @onclick="HandleBack">Back</button>
            <button type="button" class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@isSubmitting">
                @if (isSubmitting)
                {
                    <span>Submitting...</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public WorkHistory? Work { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? errorMessage;

    private async Task HandleSubmit()
    {
        if (Personal is null || Work is null || References is null || CoverLetter is null)
        {
            errorMessage = "Application data is incomplete.";
            return;
        }

        isSubmitting = true;
        errorMessage = null;

        try
        {
            var application = new JobApplication(Personal, Work, References, CoverLetter);
            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

