arguments.file_text:
@page "/apply"
@using sv_62cf6b2af18a4a4daf0b25f7a6865164.Components.Pages.Apply
@using sv_62cf6b2af18a4a4daf0b25f7a6865164.Models
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Info="personalInfo" OnNext="HandlePersonalNext" />
            break;
        case 1:
            <WorkHistoryStep History="workHistory" OnNext="HandleWorkNext" OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="references" OnNext="HandleReferencesNext" OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep Personal="personalInfo" Work="workHistory" References="references"
                        CoverLetter="coverLetter" OnEditSection="GoToStep" OnBack="GoBack" />
            break;
    }
</div>

@code {
    private int currentStep;
    private PersonalInfo? personalInfo;
    private WorkHistory? workHistory;
    private List<Reference>? references;
    private string? coverLetter;

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalInfo = info;
        currentStep = 1;
    }

    private void HandleWorkNext(WorkHistory history)
    {
        workHistory = history;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        currentStep = 4;
    }
}

.application-container {
    max-width: 800px;
    margin: 2rem auto;
    padding: 1.5rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #6c757d;
}

.step.active .step-circle {
    background: #0d6efd;
    border-color: #0d6efd;
    color: #fff;
}

.step.completed .step-circle {
    background: #198754;
    border-color: #198754;
    color: #fff;
}

.step.dimmed .step-circle {
    opacity: 0.5;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    text-align: center;
    color: #6c757d;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step.dimmed .step-label {
    opacity: 0.5;
}

.checkmark {
    font-size: 1rem;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    margin: 0 0.5rem;
    margin-bottom: 1.5rem;
}

.step-connector.completed {
    background: #198754;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 1.5rem;
}

.step-content h3 {
    margin-bottom: 1.5rem;
    color: #212529;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.3rem;
    color: #495057;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 1rem;
    line-height: 1.5;
    transition: border-color 0.15s ease-in-out;
}

.form-control:focus {
    border-color: #86b7fe;
    outline: 0;
    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.25);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal !important;
    margin-top: 0.4rem;
}

/* Buttons */
.btn {
    padding: 0.5rem 1.25rem;
    border: 1px solid transparent;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    text-decoration: none;
    display: inline-block;
}

.btn:disabled {
    opacity: 0.65;
    cursor: not-allowed;
}

.btn-primary {
    background: #0d6efd;
    border-color: #0d6efd;
    color: #fff;
}

.btn-secondary {
    background: #6c757d;
    border-color: #6c757d;
    color: #fff;
}

.btn-success {
    background: #198754;
    border-color: #198754;
    color: #fff;
}

.btn-outline-secondary {
    background: transparent;
    border-color: #6c757d;
    color: #6c757d;
}

.btn-outline-danger {
    background: transparent;
    border-color: #dc3545;
    color: #dc3545;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    padding: 0;
    text-decoration: underline;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.875rem;
}

.btn-lg {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #dee2e6;
}

/* Work Entry & Reference Forms */
.work-entry-form,
.reference-form {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.entry-header h4,
.reference-form h4 {
    margin: 0;
    font-size: 1rem;
    color: #495057;
}

/* Cover Letter */
.cover-letter-textarea {
    resize: vertical;
    min-height: 200px;
}

.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.3rem;
}

.char-count.over-limit {
    color: #dc3545;
    font-weight: bold;
}

/* Review */
.review-section {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h4 {
    margin: 0;
    font-size: 1rem;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 600;
    color: #495057;
}

.review-section dd {
    margin: 0;
}

.review-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #e9ecef;
}

.review-entry:last-child {
    border-bottom: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 0.75rem;
    border-radius: 4px;
    max-height: 200px;
    overflow-y: auto;
}

/* Alerts */
.alert {
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
}

.alert-danger {
    background: #f8d7da;
    border: 1px solid #f5c2c7;
    color: #842029;
}

.alert-success {
    background: #d1e7dd;
    border: 1px solid #badbcc;
    color: #0f5132;
}

.text-muted {
    color: #6c757d;
}

