private bool IsCurrent => Entry.EndDate is null;

private async Task UpdateEntry(WorkEntry updated)
{
    await OnEntryChanged.InvokeAsync(updated);
}

private async Task HandleEndDateChange(ChangeEventArgs e)
{
    var value = (string?)e.Value;
    var endDate = string.IsNullOrEmpty(value) ? (DateTime?)null : DateTime.Parse(value);
    await UpdateEntry(Entry with { EndDate = endDate });
}

private async Task HandleCurrentToggle(ChangeEventArgs e)
{
    var isCurrent = (bool)(e.Value ?? false);
    var updated = isCurrent
        ? Entry with { EndDate = null }
        : Entry with { EndDate = DateTime.Today };
    await OnEntryChanged.InvokeAsync(updated);
}

